from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes):
        self.capacity = max(0, int(capacity_bytes))
        self.recent = OrderedDict()
        self.frequent = OrderedDict()
        self.ghost_recent = OrderedDict()
        self.ghost_frequent = OrderedDict()
        self.recent_bytes = 0
        self.frequent_bytes = 0
        self.used = 0
        self.target = self.capacity // 2
        self.ghost_bytes = 0
        self.ghost_limit = max(64, min(1 << 20, 2 * max(1, self.capacity)))
        self.ghost_count_limit = 4096
        self.clock = 0

    def _forget_ghost(self, key):
        value = self.ghost_recent.pop(key, None)
        if value is not None:
            self.ghost_bytes -= value[0]
        value = self.ghost_frequent.pop(key, None)
        if value is not None:
            self.ghost_bytes -= value[0]

    def _remember_ghost(self, key, size, kind):
        self._forget_ghost(key)
        self.clock += 1
        value = (max(1, int(size)), self.clock)
        if kind == 1:
            self.ghost_recent[key] = value
        else:
            self.ghost_frequent[key] = value
        self.ghost_bytes += value[0]
        self._trim_ghosts()

    def _trim_ghosts(self):
        while (self.ghost_bytes > self.ghost_limit or
               len(self.ghost_recent) + len(self.ghost_frequent) > self.ghost_count_limit):
            source = None
            oldest = None
            for ghosts in (self.ghost_recent, self.ghost_frequent):
                if ghosts:
                    value = next(iter(ghosts.values()))
                    if oldest is None or value[1] < oldest[1]:
                        oldest = value
                        source = ghosts
            _, value = source.popitem(last=False)
            self.ghost_bytes -= value[0]

    def _adjust_target(self, kind):
        if self.capacity <= 0:
            return
        recent_bytes = sum(value[0] for value in self.ghost_recent.values())
        frequent_bytes = sum(value[0] for value in self.ghost_frequent.values())
        if kind == 1:
            delta = (self.capacity if recent_bytes == 0 else
                     max(1, min(self.capacity, frequent_bytes // recent_bytes or 1)))
            self.target = min(self.capacity, self.target + delta)
        else:
            delta = (self.capacity if frequent_bytes == 0 else
                     max(1, min(self.capacity, recent_bytes // frequent_bytes or 1)))
            self.target = max(0, self.target - delta)

    def _remove_resident(self, key):
        value = self.recent.pop(key, None)
        if value is not None:
            self.recent_bytes -= value[0]
            self.used -= value[0]
            return value
        value = self.frequent.pop(key, None)
        if value is not None:
            self.frequent_bytes -= value[0]
            self.used -= value[0]
            return value
        return None

    def _retract_resident(self, key, kind):
        value = self.recent.pop(key, None)
        if value is not None:
            self.recent_bytes -= value[0]
            self.used -= value[0]
            self._remember_ghost(key, value[0], kind)
            return key
        value = self.frequent.pop(key, None)
        if value is not None:
            self.frequent_bytes -= value[0]
            self.used -= value[0]
            self._remember_ghost(key, value[0], kind)
            return key
        return None

    def _evict_one(self, mode):
        choose_recent = False
        if mode == 1 and self.recent and self.recent_bytes >= self.target:
            choose_recent = True
        elif mode == 2 and self.frequent and self.recent_bytes <= self.target:
            choose_recent = False
        elif self.recent and self.recent_bytes > self.target:
            choose_recent = True
        elif self.recent and not self.frequent:
            choose_recent = True

        if choose_recent and self.recent:
            key = next(iter(self.recent))
            return self._retract_resident(key, 1)
        if self.frequent:
            key = next(iter(self.frequent))
            return self._retract_resident(key, 2)
        if self.recent:
            key = next(iter(self.recent))
            return self._retract_resident(key, 1)
        return None

    def _make_room(self, incoming, mode):
        evicted = []
        while self.used + incoming > self.capacity:
            key = self._evict_one(mode)
            if key is None:
                break
            evicted.append(key)
        return evicted

    def access(self, key, size, now):
        key = int(key)
        size = int(size)

        resident = self.recent.get(key)
        resident_kind = 1
        if resident is None:
            resident = self.frequent.get(key)
            resident_kind = 2

        if resident is not None:
            hits = resident[2] + 1
            self._remove_resident(key)
            if size <= 0 or size > self.capacity:
                return [key]
            evicted = self._make_room(size, 0)
            if self.used + size > self.capacity:
                return evicted + [key]
            self.clock += 1
            self.frequent[key] = (size, self.clock, hits)
            self.frequent_bytes += size
            self.used += size
            return evicted

        mode = 1 if key in self.ghost_recent else 2 if key in self.ghost_frequent else 0
        if size <= 0 or size > self.capacity:
            return []

        if mode:
            self._adjust_target(mode)
            self._forget_ghost(key)

        evicted = self._make_room(size, mode)
        if self.used + size > self.capacity:
            return evicted

        self.clock += 1
        if mode:
            self.frequent[key] = (size, self.clock, 1)
            self.frequent_bytes += size
        else:
            self.recent[key] = (size, self.clock, 1)
            self.recent_bytes += size
        self.used += size
        return evicted
